'use client';

import { useState, type FormEvent } from 'react';
import { countryOptions } from '@/content/countries';

const roles = [['artist', 'Artist'], ['curator', 'Curator'], ['culturalWorker', 'Cultural worker'], ['researcher', 'Researcher'], ['educator', 'Educator'], ['organisation', 'Organisation / institution'], ['student', 'Student'], ['other', 'Other']] as const;
const interests = [['art', 'Art & artistic practice'], ['research', 'Decolonial research'], ['institutions', 'Cultural institutions'], ['education', 'Education'], ['archives', 'Archives & memory'], ['community', 'Community / collective practice'], ['other', 'Other']] as const;
export interface CommunityFormLabels { heading: string; intro: string; requiredNote: string; firstName: string; lastName: string; email: string; city: string; country: string; describes: string; describesOptions: Record<(typeof roles)[number][0], string>; website: string; interested: string; interestedOptions: Record<(typeof interests)[number][0], string>; openQuestion: string; optional: string; consent: string; submit: string; submitting: string; success: string; whatsappCta: string; invalid: string; unavailable: string; providerError: string; }

export function CommunitySignupForm({ labels, whatsappUrl }: { labels: CommunityFormLabels; whatsappUrl: `https://${string}` | null }) {
  const [state, setState] = useState<'idle' | 'sending' | 'success' | 'error'>('idle'); const [error, setError] = useState(''); const [interested, setInterested] = useState<string[]>([]);
  async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form = new FormData(event.currentTarget); const payload = { firstName: String(form.get('firstName') ?? '').trim(), lastName: String(form.get('lastName') ?? '').trim(), email: String(form.get('email') ?? '').trim(), city: String(form.get('city') ?? '').trim(), country: String(form.get('country') ?? ''), describes: String(form.get('describes') ?? ''), website: String(form.get('website') ?? '').trim(), interested, openQuestion: String(form.get('openQuestion') ?? '').trim(), consent: form.get('consent') === 'on', honeypot: String(form.get('company') ?? '') }; if (!payload.firstName || !payload.lastName || !payload.email || !payload.city || !payload.country || !payload.describes || !payload.consent) { setError(labels.invalid); setState('error'); return; } setState('sending'); setError(''); try { const response = await fetch('/api/community', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(payload) }); if (!response.ok) { const body = (await response.json().catch(() => ({}))) as { error?: string }; throw new Error(body.error === 'community_not_configured' ? 'unavailable' : 'provider'); } setState('success'); } catch (cause) { setState('error'); setError(cause instanceof Error && cause.message === 'unavailable' ? labels.unavailable : labels.providerError); } }
  if (state === 'success') return <div className="v5-community-success" role="status"><p>{labels.success}</p>{whatsappUrl && <a className="solid-link" href={whatsappUrl} target="_blank" rel="noopener noreferrer">{labels.whatsappCta} ↗</a>}</div>;
  return <form className="v5-community-form" onSubmit={submit} noValidate><p>{labels.intro}</p><p className="v5-community-required">{labels.requiredNote}</p><label>{labels.firstName}<input name="firstName" required autoComplete="given-name" /></label><label>{labels.lastName}<input name="lastName" required autoComplete="family-name" /></label><label>{labels.email}<input name="email" type="email" required autoComplete="email" /></label><label>{labels.city}<input name="city" required autoComplete="address-level2" /></label><label>{labels.country}<select name="country" required defaultValue=""><option value="" disabled>—</option>{countryOptions.map(([value, name]) => <option key={value} value={value}>{name}</option>)}</select></label><label>{labels.describes}<select name="describes" required defaultValue=""><option value="" disabled>—</option>{roles.map(([value, key]) => <option key={value} value={key}>{labels.describesOptions[value]}</option>)}</select></label><label>{labels.website} <span className="v5-community-optional">({labels.optional})</span><input name="website" type="text" autoComplete="url" /></label><fieldset><legend>{labels.interested} <span className="v5-community-optional">({labels.optional})</span></legend>{interests.map(([value, key]) => <label className="v5-community-check" key={value}><input type="checkbox" checked={interested.includes(key)} onChange={(event) => setInterested((current) => event.target.checked ? [...current, key] : current.filter((item) => item !== key))} />{labels.interestedOptions[value]}</label>)}</fieldset><label>{labels.openQuestion} <span className="v5-community-optional">({labels.optional})</span><textarea name="openQuestion" rows={4} /></label><label className="v5-community-consent"><input name="consent" type="checkbox" required />{labels.consent}</label><label className="v5-community-honeypot" aria-hidden="true">Company<input name="company" tabIndex={-1} autoComplete="off" /></label>{state === 'error' && <p className="v5-community-error" role="alert">{error}</p>}<button className="solid-link" type="submit" disabled={state === 'sending'}>{state === 'sending' ? labels.submitting : labels.submit}</button></form>;
}
